  "diagnostics": {
    "step_1_service_status": {
      "tool": "service_status",
      "target": "app",
      "purpose": "Provjera je li servis aplikacije u pokretu"
    },
    "step_2_port_check": {
      "tool": "port_check",
      "target": 3000,
      "purpose": "Verifikacija je li port 3000 otvoren i sluša zahtjeve"
